import Foundation

/// An immutable Hugging Face revision with every file's size and SHA-256, for
/// models the app downloads file by file (Qwen3-ASR and WhisperKit). The bundled
/// `local-pinned-models.json` is generated by `scripts/pin-hub-models.py`.
public struct PinnedHubArtifact: Codable, Sendable, Identifiable, Equatable {
    public struct File: Codable, Sendable, Equatable {
        public let path: String
        public let bytes: Int64
        public let sha256: String
    }
    public let id: String
    public let repository: String
    public let revision: String
    /// Repository folder holding the files; empty for the repository root.
    public let directory: String
    public let files: [File]

    public var bytes: Int64 { files.reduce(0) { $0 + $1.bytes } }
    public var sizeLabel: String { ByteCountFormatter.string(fromByteCount: bytes, countStyle: .decimal) }

    public func url(for file: File) -> URL {
        let path = (directory.isEmpty ? "" : directory + "/") + file.path
        let encoded = path.addingPercentEncoding(withAllowedCharacters: .urlPathAllowed) ?? path
        return URL(string: "https://huggingface.co/\(repository)/resolve/\(revision)/\(encoded)")!
    }

    /// Transfers into `folder`, refusing manifest paths that would escape it.
    func transferFiles(into folder: URL) throws -> [ModelDownloadTransfer.File] {
        let root = folder.standardizedFileURL.resolvingSymlinksInPath().path + "/"
        return try files.map { file in
            guard !file.path.isEmpty, !file.path.hasPrefix("/"), !file.path.split(separator: "/").contains("..") else {
                throw ModelDownloader.DownloadError.unsafePath(file.path)
            }
            let destination = folder.appendingPathComponent(file.path)
            guard destination.standardizedFileURL.resolvingSymlinksInPath().path.hasPrefix(root) else {
                throw ModelDownloader.DownloadError.unsafePath(file.path)
            }
            return .init(url: url(for: file), destination: destination, size: file.bytes, sha256: file.sha256)
        }
    }
}

public enum PinnedHubModelCatalog {
    public static let artifacts: [PinnedHubArtifact] = {
        guard let url = Bundle.module.url(forResource: "local-pinned-models", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let artifacts = try? JSONDecoder().decode([PinnedHubArtifact].self, from: data) else {
            preconditionFailure("The bundled pinned model manifest is missing or invalid.")
        }
        return artifacts
    }()
    private static let byID = Dictionary(uniqueKeysWithValues: artifacts.map { ($0.id, $0) })

    public static func qwen3(_ modelId: String) -> PinnedHubArtifact? { byID["qwen3:\(modelId)"] }
    public static func whisper(_ variant: WhisperModelVariant) -> PinnedHubArtifact? { byID["whisper:\(variant.rawValue)"] }
    public static var whisperTokenizer: PinnedHubArtifact? { byID["whisper-tokenizer"] }
}
